import os,re
DECL=re.compile(r'^\s*(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|scoped\s+)*(theorem|lemma|def|abbrev|instance|structure|class|inductive)\b(\s+([A-Za-z_][\w.\'!?]*))?')
def strip_comments(text):
    # remove block comments (incl docstrings) non-greedily with nesting-agnostic approach
    out=[];i=0;depth=0
    while i<len(text):
        if text.startswith('/-',i):
            depth+=1;i+=2;continue
        if text.startswith('-/',i):
            if depth>0: depth-=1
            i+=2;continue
        if depth==0:
            if text.startswith('--',i):
                j=text.find('\n',i); i=(len(text) if j<0 else j); continue
            out.append(text[i])
        else:
            if text[i]=='\n': out.append('\n')
        i+=1
    return ''.join(out)

targets={'HasPicScheme':0,'HasPicSchemeEt':0,'HasRationalPoint':0,'HasDivFunctor':0,'HasAbelMap':0,'HasSmoothProperQuotient':0,'PicSharpRepresentable':0,'PicSchemeLocallyOfFiniteType':0}
detail={k:{} for k in targets}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in sorted(fns):
        if not fn.endswith('.lean'): continue
        p=os.path.join(dp,fn)
        src=strip_comments(open(p,encoding='utf8',errors='replace').read())
        lines=src.split('\n')
        # collect declaration blocks: from a DECL line until the next DECL line at col 0
        idxs=[i for i,l in enumerate(lines) if DECL.match(l) and not l.startswith(' ')]
        for a,i in enumerate(idxs):
            j=idxs[a+1] if a+1<len(idxs) else len(lines)
            block='\n'.join(lines[i:j])
            # signature = up to first ':=' or 'where' or ' := by'
            m=re.search(r':=|\bwhere\b', block)
            sig=block[:m.start()] if m else block
            name=DECL.match(lines[i]).group(3) or '?'
            for t in targets:
                if re.search(r'\['+t+r'\b', sig):
                    if t=='HasPicScheme' and re.search(r'\[HasPicSchemeEt\b',sig) and not re.search(r'\[HasPicScheme\s',sig) and not re.search(r'\[HasPicScheme\]',sig):
                        continue
                    targets[t]+=1
                    detail[t].setdefault(p,[]).append(name)
print("DECLARATIONS binding each class (comments stripped, signature only):")
for t,c in sorted(targets.items(), key=lambda x:-x[1]):
    print(f"  {t:32s} {c}")
print()
for t in ('HasPicScheme','HasPicSchemeEt'):
    print(f"--- {t} ({targets[t]} decls) ---")
    for p,ns in sorted(detail[t].items()):
        print(f"  {p}: {len(ns)}")
